137 // Close implements the Executor interface.
138 func (e *CTEExec) Close() (firstErr error) {
139 	func() {
140 		e.producer.resTbl.Lock()
141 		defer e.producer.resTbl.Unlock()
142 		if e.producer.executorOpened {
143 			failpoint.Inject("mock_cte_exec_panic_avoid_deadlock", func(v failpoint.Value) {
144 				ok := v.(bool)
145 				if ok {
146 					// mock an oom panic, returning ErrMemoryExceedForQuery for error identification in recovery work.
147 					panic(exeerrors.ErrMemoryExceedForQuery)
148 				}
149 			})
150 			// closeProducerExecutor() only close seedExec and recursiveExec, will not touch resTbl.
151 			// It means you can still read resTbl after call closeProducerExecutor().
152 			// You can even call all three functions(openProducerExecutor/genCTEResult/closeProducerExecutor) in CTEExec.Next().
153 			// Separating these three function calls is only to follow the abstraction of the volcano model.
154 			err := e.producer.closeProducerExecutor()
155 			firstErr = setFirstErr(firstErr, err, "close cte producer error")
156 			if !e.producer.hasCTEResult() {
157 				// CTE result is not generated, in this case, we reset it
158 				err = e.producer.reset()
159 				firstErr = setFirstErr(firstErr, err, "close cte producer error")
160 			}
161 		}
162 	}()
163 	err := e.BaseExecutor.Close()
164 	firstErr = setFirstErr(firstErr, err, "close cte children error")
165 	return
166 }
